"""Ipsec validate"""
from __future__ import division
from __future__ import print_function
from builtins import str
from builtins import range
from builtins import object
import re
from robot.libraries import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.ipsec.command_builder import CommandBuilder
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler

logger = BackgroundLogger.Instance()


class ipsec_validate(object):
    """Ipsec validate"""

    def __init__(self):
        self.config = ConfigHandler.get_config()
        self.comunicator_obj = Communicator()
        self.cmd_builder = CommandBuilder()

    def check_enc_list(self, ENC_list, ENC_protocol_tunnel, status_output, tunnel):
        """Check enc list"""
        if ENC_list:
            enc_protocol, enc_ip1, enc_ip2 = ENC_list.split(',', 2)
            logger.debug("Validating Protocol provided:")
            protocol = self.get_encrpyption_protocol(enc_ip1, enc_ip2, enc_protocol[4:])
            tunnel.append([enc_ip1, enc_ip2])
            for line in status_output:
                self.find_protocol(ENC_protocol_tunnel, line, protocol, status_output)

            self.validate_the_user_provided_ips(tunnel, ENC_protocol_tunnel)

    def check_esp_list(self, ESP_list, ESP_list_to_validate, esp_tunnels):
        """Check esp list"""
        if ESP_list:
            ESP_eachtunnel_list = ESP_list.split(',')
            for tunnel_unformatted in ESP_eachtunnel_list:
                ESP_list_to_validate.append(tunnel_unformatted.split('=>'))
            logger.debug("Validating ESP ips provided:")
            self.validate_the_user_provided_ips(ESP_list_to_validate, esp_tunnels)

    def check_for_ike_list(self, IKE_list, IKE_list_to_validate, ike_tunnels):
        """Check for ike list"""
        if IKE_list:
            IKE_eachtunnel_list = IKE_list.split(',')
            for tunnel_unformatted in IKE_eachtunnel_list:
                IKE_list_to_validate.append(tunnel_unformatted.split('=>'))
            logger.debug("Validating IKE ips provided:")
            self.validate_the_user_provided_ips(IKE_list_to_validate, ike_tunnels)

    def check_for_ike_esp_list(self, IKE_list, IKE_list_to_validate, ike_tunnels,
                               esp_tunnels, all_ips):
        if IKE_list:
            # IKE_list_to_validate = self._fetch_ips_from_list_to_validate(IKE_list)
            logger.debug("Validating IKE and ESP ips provided against {} and {}:".format(
                ike_tunnels, esp_tunnels))
            self.validate_the_user_provided_fh_ips(IKE_list, ike_tunnels, esp_tunnels, all_ips)

    def _fetch_ips_from_list_to_validate(self, list_item):
        list_to_validate = []
        for each_item_in_list in list_item:
            list_to_validate.append(each_item_in_list[0].split('=>'))
            list_to_validate.append(each_item_in_list[1])
        return list_to_validate

    def check_if_tunnels_not_established(self, tunnels_not_established):
        """Check if tunnels not established"""
        if tunnels_not_established:
            for tunnels in tunnels_not_established:
                BuiltIn.BuiltIn().fail(
                    "Tunnels not established between " + tunnels[0] + " and " + tunnels[1])

    def check_for_esp_tunnels(self, esp_tunnels):
        """Check for esp tunnels"""
        if esp_tunnels:
            for tunnels in esp_tunnels:
                logger.debug("ESP Tunnels are Installed between " + tunnels[0] + " and " + tunnels[1])
            logger.debug("Number of ESP tunnels Established = " + str(len(esp_tunnels)))

    def check_for_ike(self, ike_tunnels):
        """Check for ike"""
        if ike_tunnels:
            for tunnels in ike_tunnels:
                logger.debug("IKE Tunnels are Established between " + tunnels[0] + " and " + tunnels[1])
            logger.debug("Number of IKE tunnels Established = " + str(len(ike_tunnels)))

    def find_protocol(self, ENC_protocol_tunnel, line, protocol, status_output):
        """Find protocol"""
        if protocol in line:
            if "IKE proposal" in line:
                protocol_line = status_output[status_output.index(line) - 2]
                match_protocol = re.findall(r'[0-9]+(?:\.[0-9]+){3}', protocol_line, re.U | re.I)
                ENC_protocol_tunnel.append(match_protocol)

            if "rekeying" in line:
                protocol_line = status_output[status_output.index(line) + 1]
                match_protocol = re.findall(r'[0-9]+(?:\.[0-9]+){3}', protocol_line, re.U | re.I)
                ENC_protocol_tunnel.append(match_protocol)

        else:
            logger.debug("Protocol not found")

    def get_encrpyption_protocol(self, enc_ip1, enc_ip2, protocol):
        """Get encryption protocol"""
        if protocol == '3DES_192_CBC':
            protocol = '3DES_CBC'
        elif protocol == 'AES_128_CBC':
            protocol = 'AES_CBC_128'
        elif protocol == 'ENC_NULL':
            protocol = 'NULL'
        elif protocol == 'AES_128_CBC_OR_3DES_192_CBC':
            protocol = 'CBC'
        else:
            raise Exception("Protocol not supoorted")
        logger.debug("protocol is : " + protocol + " enc ip1 = " + enc_ip1 + " enc ip2 = " + enc_ip2)
        return protocol

    def validate_the_user_provided_ips(self, ip_list, ip_tunnels):
        """Validate the suer provided ips"""
        tunnel_searched_and_not_found = []
        for required_tunnel in ip_list:
            flag = False
            for actual_tunnel in ip_tunnels:
                if len(required_tunnel) == 2:
                    logger.debug("len 2")
                    if (required_tunnel[0] in actual_tunnel) and (required_tunnel[1] in actual_tunnel):
                        logger.debug("Tunnel exists between " + actual_tunnel[0] + " and " + actual_tunnel[1])
                        flag = True
                elif len(required_tunnel) == 1:
                    for ip in required_tunnel:
                        if ip in actual_tunnel:
                            logger.debug("Tunnel exists for " + ip + " between " + actual_tunnel[0] + " and " + actual_tunnel[1])
                            flag = True
            if not flag:
                tunnel_searched_and_not_found.append(required_tunnel)
                logger.debug(tunnel_searched_and_not_found)

        if tunnel_searched_and_not_found:
            error_ips = "Tunnels not established for below ips:"
            for ip in tunnel_searched_and_not_found:
                error_ips = error_ips + "\n" + str(ip)
                BuiltIn.BuiltIn().fail(error_ips)

    def validate_the_user_provided_fh_ips(self, ike_list, ike_tunnels, esp_tunnels, all_tunnel_ips):
        ike_expected_tunnel_not_found = []
        ike_unexpected_tunnel_found = []
        esp_expected_tunnel_not_found = []
        esp_unexpected_tunnel_found = []
        esp_verification = True
        ike_verification = True
        check_for_non_existence = self._fetch_not_expected_tunnel(ike_list)
        logger.debug("Check for non existence {}".format(check_for_non_existence))
        for item in all_tunnel_ips:
            ike_ip_list = item.split('=>')
            if ike_ip_list in ike_tunnels:
                # ike tunnel found, before passing check for negative condition
                if check_for_non_existence:
                    for not_ip in check_for_non_existence:
                        logger.debug("checking of non existence of IKE tunnel ip {} in {}".format(not_ip, ike_ip_list))
                        if ike_ip_list == not_ip:
                            logger.debug("Tunnel {} was not expected but found".format(ike_ip_list))
                            ike_unexpected_tunnel_found.append(ike_ip_list)
                            ike_verification = False
                else:
                    logger.debug("IKE Tunnel {} was expected and found ".format(ike_ip_list))
                for esp_item in all_tunnel_ips[item]:
                    esp_ip_list = esp_item[0].split('=>')
                    if esp_ip_list in esp_tunnels:
                        # esp tunnel found, before passing check for negative condition
                        if esp_item[1] == 'false':
                            logger.debug("ESP tunnel {} was not expected but found".format(esp_ip_list))
                            esp_unexpected_tunnel_found.append(esp_ip_list)
                            esp_verification = False
                        elif esp_item[1] == 'true':
                            logger.debug("ESP tunnel {} was expected and found".format(esp_ip_list))
                    else:
                        # esp tunnel not found, before failing check for negative condition
                        if esp_item[1] == 'false':
                            logger.debug("ESP tunnel {} was not expected and not found".format(
                                esp_ip_list))
                        elif esp_item[1] == 'true':
                            logger.debug("ESP tunnel {} was expected and not found".format(esp_ip_list))
                            esp_expected_tunnel_not_found.append(esp_ip_list)
                            esp_verification = False
            else:
                # ike tunnel not found, before failing check for negative condition
                if check_for_non_existence:
                    for not_ip in check_for_non_existence:
                        logger.debug("checking of non existence of IKE tunnel ip {} in {}".format(not_ip, ike_ip_list))
                        if ike_ip_list == not_ip:
                            logger.debug("Tunnel {} was not expected and not found".format(ike_ip_list))
                        else:
                            logger.debug("Tunnel {} was not expected but found".format(ike_ip_list))
                            ike_unexpected_tunnel_found.append(ike_ip_list)
                            ike_verification = False
                elif not check_for_non_existence:
                    logger.debug("IKE tunnel {} was expected but not found".format(
                        ike_ip_list))
                    ike_expected_tunnel_not_found.append(ike_ip_list)

        if not ike_verification:
            self._check_for_failure('IKE',
                                    ike_expected_tunnel_not_found, ike_unexpected_tunnel_found)
            BuiltIn.BuiltIn().fail('IKE tunnels verification failed')
        if not esp_verification:
            self._check_for_failure('ESP',
                                    esp_expected_tunnel_not_found, esp_unexpected_tunnel_found)
            BuiltIn.BuiltIn().fail('ESP tunnels verification failed')

    def _fetch_not_expected_tunnel(self, ike_tunnel_list):
        tunnels_not_required = []
        [tunnels_not_required.append(ike_tunnel[0].split('=>')) for ike_tunnel in ike_tunnel_list if 
         ike_tunnel[
             1] == 'false']
        return tunnels_not_required

    def _check_for_failure(self, tunnel, expected_tunnel_not_found,
                           unexpected_tunnel_found):
        if expected_tunnel_not_found:
            logger.debug("{} tunnels {} were expected but not found".format(tunnel,
                                                                            expected_tunnel_not_found))
        elif unexpected_tunnel_found:
            logger.debug("{} tunnels {} were not expected but found".format(tunnel,
                                                                            unexpected_tunnel_found))

    def _check_if_tunnel_established(self, ip_tunnels, required_tunnel):
        flag = False
        for actual_tunnel in ip_tunnels:
            if len(required_tunnel) == 2:
                logger.debug("len 2")
                if (required_tunnel[0] in actual_tunnel[0]) and (
                        required_tunnel[1] in actual_tunnel[1]):
                    logger.debug("Tunnel exists between " + actual_tunnel[0] + " and " + actual_tunnel[
                        1])
                    flag = True
            elif len(required_tunnel) == 1:
                for ip in required_tunnel:
                    if ip in actual_tunnel:
                        logger.debug("Tunnel exists for " + ip + " between " + actual_tunnel[0] + " and " + actual_tunnel[1])
                        flag = True
        return flag

    def _check_for_tunnel_exception(self, ip_tunnels, required_tunnel, should_exist):
        flag = self._check_if_tunnel_established(ip_tunnels, required_tunnel)
        tunnel_searched_and_not_found = []
        unexpected_tunnel_found = []
        if not flag and should_exist == 'true':
            tunnel_searched_and_not_found.append(required_tunnel)
            logger.debug(tunnel_searched_and_not_found)
        elif flag:
            if should_exist == 'false':
                unexpected_tunnel_found.append(required_tunnel)
                logger.debug(unexpected_tunnel_found)

    def check_if_installed(self, ipsec_status_bts, count_ikep, count_secpol, local_ip_list, local_length,
                           remote_ip_list, remote_length):
        count_installed = ipsec_status_bts.count('INSTALLED')
        if count_secpol != count_installed:
            BuiltIn.BuiltIn().fail('installed tunnels do not match required number in bts')
        count_established = ipsec_status_bts.count('ESTABLISHED')
        if count_ikep != count_established:
            BuiltIn.BuiltIn().fail('established tunnels do not match required number in bts')
        string_bts = []
        for i in range(0, count_secpol):
            string_bts[i] = local_ip_list[i] / local_length[i] + " === " + remote_ip_list[i] / remote_length[i]
            if string_bts[i] not in ipsec_status_bts:
                BuiltIn.BuiltIn().fail('tunnels not established properly')
        ip = get_config_variable(["secure_gw", "ip"])
        user = get_config_variable(["secure_gw", "username"])
        password = get_config_variable(["secure_gw", "password"])
        ipsec_status_secgw = self.comunicator_obj.execute_commands_remotely_and_verify(
            ip, user, password, "ipsec status")
        count_installed_sgw = ipsec_status_secgw.count('INSTALLED')
        if count_secpol != count_installed_sgw:
            BuiltIn.BuiltIn().fail('installed tunnels do not match required number in sgw')
        count_established_sgw = ipsec_status_secgw.count('ESTABLISHED')
        if count_ikep != count_established_sgw:
            BuiltIn.BuiltIn().fail('established tunnels do not match required number in sgw')
